cat > /workspace/submission/src/ledger.rs <<'EOF'
//! Transactional certificate layer for weighted cache-group reconfigurations.
//!
//! The ledger keeps the committed configuration and certifies proposals built
//! from ordered field assignments.  Committed state is never destroyed by a
//! rejected proposal: every speculative mutation is recorded in a journal of
//! inverse operations which is replayed backwards on rejection.  All validity
//! decisions (node capacity, group homogeneity, weighted work budgets and pin
//! protection) are computed exactly on the final proposal.

use crate::solver::SolverProblem;
use std::collections::HashMap;

/// One service task bound to a template and a cache group.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Domain of every template, derived from the topology scope of the session.
///
/// `code`/`args` are the encoded topology descriptor produced by the transport
/// layer; endpoint pairs come from the routing templates themselves.
pub fn template_domains(code: usize, args: &[usize], problem: &SolverProblem) -> Vec<i64> {
    let mut out = Vec::with_capacity(problem.demands.len());
    for demand in &problem.demands {
        let src = demand.src as i64;
        let dst = demand.dst as i64;
        let value = match code {
            // clos: args = [k, pod-scope, intra]
            0 => if args[1] != 0 { src / (args[0] as i64 / 2) } else { src },
            // leaf-spine
            1 => src,
            // torus2d / torus3d: args = [n, row/line scope]
            2 | 3 => if args[1] != 0 { src / args[0] as i64 } else { src },
            // dragonfly: args = [g, a, h, 0=router 1=group 2=target]
            4 => match args[3] {
                1 => src / args[1] as i64,
                2 => src * args[0] as i64 + dst / args[1] as i64,
                _ => src,
            },
            // dragonfly-plus: args = [g, l, s, h, dense, group-scope]
            5 => {
                let span = (args[1] + args[2]) as i64;
                let leaves = args[1] as i64;
                if args[5] != 0 { src / span } else { (src / span) * leaves + src % span }
            }
            _ => src,
        };
        out.push(value);
    }
    out
}

/// Journal entry: enough information to mirror one committed mutation.
#[derive(Clone, Copy, Debug)]
enum Undo {
    Move(usize, usize),
    Bind(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

/// Start-of-transaction snapshot of a touched service task.
struct TaskSnap {
    id: usize,
    group: usize,
    template: usize,
    weight: u64,
    class: u64,
    pinned: bool,
}

/// Start-of-transaction snapshot of a group touched by a quota assignment.
struct GroupSnap {
    id: usize,
    quota: u64,
    pins: i64,
}

pub struct Ledger {
    num_nodes: usize,
    words: usize,
    /// Cache-bearing footprint of every routing template, as a bit set.
    template_fp: Vec<u64>,
    /// Cache domain of every routing template.
    dom: Vec<i64>,

    task: Vec<Task>,
    quota: Vec<u64>,
    budget: Vec<u64>,

    /// Members of each group covering each cache node.
    cnt: Vec<u32>,
    /// Union of member footprints, as a bit set.
    union_fp: Vec<u64>,
    fp_size: Vec<i64>,
    members: Vec<i64>,
    load: Vec<i64>,
    /// Distinct (domain, class) pairs present in each group.
    keys: Vec<HashMap<(i64, i64), u32>>,
    g_dom: Vec<i64>,
    g_cls: Vec<i64>,

    usage: Vec<i64>,
    caps: Vec<i64>,
    over_flag: Vec<bool>,
    work_flag: Vec<bool>,

    overcap: i64,
    mixed: i64,
    workbad: i64,
    active: i64,
    slots: i64,
    total_weight: i64,
    pins: i64,
    pin_in_group: Vec<i64>,

    revision: u64,
    journal: Vec<Undo>,
    snaps: Vec<TaskSnap>,
    group_snaps: Vec<GroupSnap>,
    task_stamp: Vec<u32>,
    task_slot: Vec<u32>,
    group_stamp: Vec<u32>,
    group_slot: Vec<u32>,
    txn: u32,
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        domains: Vec<i64>,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let num_nodes = problem.num_nodes;
        if capacities.len() != num_nodes {
            return Err("capacity count".into());
        }
        if quotas.len() != budgets.len() {
            return Err("group table".into());
        }
        if domains.len() != problem.demands.len() {
            return Err("domain table".into());
        }
        for &cap in &capacities {
            if cap > i64::MAX as u64 {
                return Err("capacity range".into());
            }
        }
        let words = num_nodes.div_ceil(64);
        let templates = problem.demands.len();
        let mut template_fp = vec![0u64; templates * words];
        for (id, demand) in problem.demands.iter().enumerate() {
            for &node in &demand.footprint {
                if node >= num_nodes {
                    return Err("footprint node".into());
                }
                template_fp[id * words + node / 64] |= 1u64 << (node % 64);
            }
        }
        let groups = quotas.len();
        for task in &tasks {
            if task.group >= groups {
                return Err("task group".into());
            }
            if task.template >= templates {
                return Err("task template".into());
            }
        }

        let mut ledger = Ledger {
            num_nodes,
            words,
            template_fp,
            dom: domains,
            task,
            quota: quotas,
            budget: budgets,
            cnt: vec![0u32; groups * num_nodes],
            union_fp: vec![0u64; groups * words],
            fp_size: vec![0i64; groups],
            members: vec![0i64; groups],
            load: vec![0i64; groups],
            keys: (0..groups).map(|_| HashMap::new()).collect(),
            g_dom: vec![-1i64; groups],
            g_cls: vec![-1i64; groups],
            usage: vec![0i64; num_nodes],
            caps: capacities.iter().map(|&x| x as i64).collect(),
            over_flag: vec![false; num_nodes],
            work_flag: vec![false; groups],
            overcap: 0,
            mixed: 0,
            workbad: 0,
            active: 0,
            slots: 0,
            total_weight: 0,
            pins: 0,
            pin_in_group: vec![0i64; groups],
            revision: 0,
            journal: Vec::new(),
            snaps: Vec::new(),
            group_snaps: Vec::new(),
            task_stamp: vec![0u32; tasks.len()],
            task_slot: vec![0u32; tasks.len()],
            group_stamp: vec![0u32; groups],
            group_slot: vec![0u32; groups],
            txn: 0,
        };
        for id in 0..ledger.task.len() {
            let group = ledger.task[id].group;
            ledger.attach(id, group);
        }
        if ledger.overcap != 0 || ledger.mixed != 0 || ledger.workbad != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(ledger)
    }

    // ---------------------------------------------------------------- state

    fn recheck_over(&mut self, node: usize) {
        let over = self.usage[node] > self.caps[node];
        if over != self.over_flag[node] {
            self.over_flag[node] = over;
            self.overcap += if over { 1 } else { -1 };
        }
    }

    fn update_work(&mut self, group: usize) {
        let bad = self.members[group] > 0
            && (self.quota[group] == 0
                || self.load[group] as i128 > self.quota[group] as i128 * self.budget[group] as i128);
        if bad != self.work_flag[group] {
            self.work_flag[group] = bad;
            self.workbad += if bad { 1 } else { -1 };
        }
    }

    fn bump_key(&mut self, group: usize, key: (i64, i64)) {
        let map = &mut self.keys[group];
        let prev = map.len();
        *map.entry(key).or_insert(0u32) += 1;
        let cur = map.len();
        if prev <= 1 && cur > 1 {
            self.mixed += 1;
        }
        if cur == 1 {
            self.g_dom[group] = key.0;
            self.g_cls[group] = key.1;
        }
    }

    fn drop_key(&mut self, group: usize, key: (i64, i64)) {
        let map = &mut self.keys[group];
        let prev = map.len();
        if let Some(count) = map.get_mut(&key) {
            *count -= 1;
            if *count == 0 {
                map.remove(&key);
            }
        }
        let cur = map.len();
        if prev > 1 && cur <= 1 {
            self.mixed -= 1;
        }
        if cur == 1 {
            if let Some(&found) = map.keys().next() {
                self.g_dom[group] = found.0;
                self.g_cls[group] = found.1;
            }
        } else if cur == 0 {
            self.g_dom[group] = -1;
            self.g_cls[group] = -1;
        }
    }

    /// Add task `id` to group `group` using its current template, weight,
    /// class and pin flag.
    fn attach(&mut self, id: usize, group: usize) {
        let template = self.task[id].template;
        let reserve = self.quota[group] as i64;
        let base = template * self.words;
        let gbase = group * self.words;
        for word_index in 0..self.words {
            let mut word = self.template_fp[base + word_index];
            while word != 0 {
                let bit = word.trailing_zeros() as usize;
                word &= word - 1;
                let node = word_index * 64 + bit;
                let slot = group * self.num_nodes + node;
                self.cnt[slot] += 1;
                if self.cnt[slot] == 1 {
                    self.union_fp[gbase + word_index] |= 1u64 << bit;
                    self.fp_size[group] += 1;
                    self.usage[node] += reserve;
                    self.slots += reserve;
                    self.recheck_over(node);
                }
            }
        }
        self.members[group] += 1;
        if self.members[group] == 1 {
            self.active += 1;
        }
        let weight = self.task[id].weight;
        self.load[group] += weight as i64;
        self.total_weight += weight as i64;
        let key = (self.dom[template], self.task[id].class as i64);
        self.bump_key(group, key);
        if self.task[id].pinned {
            self.pins += 1;
            self.pin_in_group[group] += 1;
        }
        self.update_work(group);
    }

    /// Remove task `id` from group `group` using its current fields.
    fn detach(&mut self, id: usize, group: usize) {
        let template = self.task[id].template;
        let reserve = self.quota[group] as i64;
        let base = template * self.words;
        let gbase = group * self.words;
        for word_index in 0..self.words {
            let mut word = self.template_fp[base + word_index];
            while word != 0 {
                let bit = word.trailing_zeros() as usize;
                word &= word - 1;
                let node = word_index * 64 + bit;
                let slot = group * self.num_nodes + node;
                self.cnt[slot] -= 1;
                if self.cnt[slot] == 0 {
                    self.union_fp[gbase + word_index] &= !(1u64 << bit);
                    self.fp_size[group] -= 1;
                    self.usage[node] -= reserve;
                    self.slots -= reserve;
                    self.recheck_over(node);
                }
            }
        }
        self.members[group] -= 1;
        if self.members[group] == 0 {
            self.active -= 1;
        }
        let weight = self.task[id].weight;
        self.load[group] -= weight as i64;
        self.total_weight -= weight as i64;
        let key = (self.dom[template], self.task[id].class as i64);
        self.drop_key(group, key);
        if self.task[id].pinned {
            self.pins -= 1;
            self.pin_in_group[group] -= 1;
        }
        self.update_work(group);
    }

    // ------------------------------------------------------- raw mutations

    fn set_weight_raw(&mut self, id: usize, weight: u64) {
        if self.task[id].weight == weight {
            return;
        }
        let group = self.task[id].group;
        let delta = weight as i64 - self.task[id].weight as i64;
        self.load[group] += delta;
        self.total_weight += delta;
        self.task[id].weight = weight;
        self.update_work(group);
    }

    fn set_class_raw(&mut self, id: usize, class: u64) {
        if self.task[id].class == class {
            return;
        }
        let group = self.task[id].group;
        let key = (self.dom[self.task[id].template], self.task[id].class as i64);
        self.drop_key(group, key);
        self.task[id].class = class;
        let key = (self.dom[self.task[id].template], class as i64);
        self.bump_key(group, key);
    }

    fn set_pin_raw(&mut self, id: usize, pinned: bool) {
        if self.task[id].pinned == pinned {
            return;
        }
        let group = self.task[id].group;
        self.task[id].pinned = pinned;
        if pinned {
            self.pins += 1;
            self.pin_in_group[group] += 1;
        } else {
            self.pins -= 1;
            self.pin_in_group[group] -= 1;
        }
    }

    fn set_cap_raw(&mut self, node: usize, capacity: u64) {
        let value = capacity as i64;
        if self.caps[node] == value {
            return;
        }
        self.caps[node] = value;
        self.recheck_over(node);
    }

    fn set_budget_raw(&mut self, group: usize, budget: u64) {
        if self.budget[group] == budget {
            return;
        }
        self.budget[group] = budget;
        self.update_work(group);
    }

    fn set_quota_raw(&mut self, group: usize, quota: u64) {
        if self.quota[group] == quota {
            return;
        }
        let delta = quota as i64 - self.quota[group] as i64;
        let gbase = group * self.words;
        for word_index in 0..self.words {
            let mut word = self.union_fp[gbase + word_index];
            while word != 0 {
                let bit = word.trailing_zeros() as usize;
                word &= word - 1;
                let node = word_index * 64 + bit;
                self.usage[node] += delta;
                self.recheck_over(node);
            }
        }
        self.slots += delta * self.fp_size[group];
        self.quota[group] = quota;
        self.update_work(group);
    }

    fn move_raw(&mut self, id: usize, group: usize) {
        if self.task[id].group == group {
            return;
        }
        let old = self.task[id].group;
        self.detach(id, old);
        self.task[id].group = group;
        self.attach(id, group);
    }

    fn bind_raw(&mut self, id: usize, template: usize) {
        if self.task[id].template == template {
            return;
        }
        let group = self.task[id].group;
        self.detach(id, group);
        self.task[id].template = template;
        self.attach(id, group);
    }

    // ------------------------------------------------------- journal layer

    fn apply(&mut self, edit: Edit) {
        match edit {
            Edit::Move(id, group) => {
                if self.task[id].group != group {
                    self.journal.push(Undo::Move(id, self.task[id].group));
                    self.move_raw(id, group);
                }
            }
            Edit::Bind(id, template) => {
                if self.task[id].template != template {
                    self.journal.push(Undo::Bind(id, self.task[id].template));
                    self.bind_raw(id, template);
                }
            }
            Edit::Weight(id, weight) => {
                if self.task[id].weight != weight {
                    self.journal.push(Undo::Weight(id, self.task[id].weight));
                    self.set_weight_raw(id, weight);
                }
            }
            Edit::Class(id, class) => {
                if self.task[id].class != class {
                    self.journal.push(Undo::Class(id, self.task[id].class));
                    self.set_class_raw(id, class);
                }
            }
            Edit::Pin(id, pinned) => {
                if self.task[id].pinned != pinned {
                    self.journal.push(Undo::Pin(id, self.task[id].pinned));
                    self.set_pin_raw(id, pinned);
                }
            }
            Edit::Quota(group, quota) => {
                if self.quota[group] != quota {
                    self.journal.push(Undo::Quota(group, self.quota[group]));
                    self.set_quota_raw(group, quota);
                }
            }
            Edit::Budget(group, budget) => {
                if self.budget[group] != budget {
                    self.journal.push(Undo::Budget(group, self.budget[group]));
                    self.set_budget_raw(group, budget);
                }
            }
            Edit::Cap(node, capacity) => {
                if self.caps[node] != capacity as i64 {
                    self.journal.push(Undo::Cap(node, self.caps[node] as u64));
                    self.set_cap_raw(node, capacity);
                }
            }
        }
    }

    fn rollback(&mut self) {
        while let Some(entry) = self.journal.pop() {
            match entry {
                Undo::Move(id, group) => self.move_raw(id, group),
                Undo::Bind(id, template) => self.bind_raw(id, template),
                Undo::Weight(id, weight) => self.set_weight_raw(id, weight),
                Undo::Class(id, class) => self.set_class_raw(id, class),
                Undo::Pin(id, pinned) => self.set_pin_raw(id, pinned),
                Undo::Quota(group, quota) => self.set_quota_raw(group, quota),
                Undo::Budget(group, budget) => self.set_budget_raw(group, budget),
                Undo::Cap(node, capacity) => self.set_cap_raw(node, capacity),
            }
        }
    }

    // ------------------------------------------------------- certifying

    fn snap_task(&mut self, id: usize) {
        if self.task_stamp[id] != self.txn {
            self.task_stamp[id] = self.txn;
            self.task_slot[id] = self.snaps.len() as u32;
            let task = self.task[id];
            self.snaps.push(TaskSnap {
                id,
                group: task.group,
                template: task.template,
                weight: task.weight,
                class: task.class,
                pinned: task.pinned,
            });
        }
    }

    fn snap_group(&mut self, id: usize) {
        if self.group_stamp[id] != self.txn {
            self.group_stamp[id] = self.txn;
            self.group_slot[id] = self.group_snaps.len() as u32;
            self.group_snaps.push(GroupSnap { id, quota: self.quota[id], pins: self.pin_in_group[id] });
        }
    }

    pub fn certificate(&self, query: &Query) -> Certificate {
        let totals = [
            self.active as u64,
            self.slots as u64,
            self.total_weight as u64,
            self.pins as u64,
        ];
        let mut groups = Vec::with_capacity(query.groups.len());
        for &id in &query.groups {
            let empty = self.members[id] == 0;
            groups.push([
                id as i64,
                self.members[id],
                self.load[id],
                self.quota[id] as i64,
                self.budget[id] as i64,
                self.fp_size[id],
                if empty { -1 } else { self.g_dom[id] },
                if empty { -1 } else { self.g_cls[id] },
            ]);
        }
        let mut nodes = Vec::with_capacity(query.nodes.len());
        for &id in &query.nodes {
            nodes.push([id as u64, self.usage[id] as u64, self.caps[id] as u64]);
        }
        let mut tasks = Vec::with_capacity(query.tasks.len());
        for &id in &query.tasks {
            let task = &self.task[id];
            tasks.push([
                id as u64,
                task.group as u64,
                task.template as u64,
                task.weight,
                task.class,
                task.pinned as u64,
            ]);
        }
        Certificate { totals, groups, nodes, tasks }
    }

    pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
        if expected != self.revision {
            let certificate = self.certificate(query);
            return Outcome {
                accepted: false,
                revision: self.revision,
                violations: None,
                certificate,
            };
        }
        self.txn = self.txn.wrapping_add(1);
        self.journal.clear();
        self.snaps.clear();
        self.group_snaps.clear();
        // Start-of-transaction protection set: read every value a pin or a
        // quota assignment can compare against before any edit is applied.
        for edit in edits {
            match *edit {
                Edit::Move(id, _)
                | Edit::Bind(id, _)
                | Edit::Weight(id, _)
                | Edit::Class(id, _)
                | Edit::Pin(id, _) => self.snap_task(id),
                Edit::Quota(group, _) => self.snap_group(group),
                Edit::Budget(_, _) | Edit::Cap(_, _) => {}
            }
        }
        for &edit in edits {
            self.apply(edit);
        }
        // Pin violations, counted once per protected task.
        let mut violated = 0i64;
        let mut moved_diff: HashMap<usize, i64> = HashMap::new();
        let snaps = self.snaps.clone();
        for snap in &snaps {
            if !snap.pinned {
                continue;
            }
            let task = &self.task[snap.id];
            let differs = task.group != snap.group
                || task.template != snap.template
                || task.weight != snap.weight
                || task.class != snap.class;
            if differs {
                violated += 1;
                if self.group_stamp[snap.group] == self.txn {
                    *moved_diff.entry(snap.group).or_insert(0i64) += 1;
                }
            }
        }
        for snap in &self.group_snaps {
            if self.quota[snap.id] != snap.quota {
                let protected = snap.pins - moved_diff.get(&snap.id).copied().unwrap_or(0);
                violated += protected;
            }
        }
        let violations = [
            self.overcap as u64,
            self.mixed as u64,
            self.workbad as u64,
            violated as u64,
        ];
        let accepted = violations.iter().all(|&count| count == 0);
        if accepted {
            self.revision += 1;
            self.journal.clear();
        } else {
            self.rollback();
        }
        let certificate = self.certificate(query);
        Outcome { accepted, revision: self.revision, violations: Some(violations), certificate }
    }
}
