#!/usr/bin/env python3
"""Local harness mimicking public_check.execute without the seccomp policy."""
import json, math, os, pathlib, subprocess, sys

def pairs(items):
    obj = {}
    for key, val in items:
        if key in obj: raise ValueError('duplicate output key')
        obj[key] = val
    return obj

def nonfinite(v): raise ValueError('nonfinite output')
def finite_float(v):
    p = float(v)
    if not math.isfinite(p): raise ValueError('nonfinite output')
    return p

def strict_load(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs, parse_constant=nonfinite, parse_float=finite_float)

def same(a, b):
    if type(a) is not type(b): return False
    if isinstance(a, dict): return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list): return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def run(candidate, data_bytes, timeout=180):
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0'}
    p = subprocess.run([sys.executable, '-B', str(candidate)], input=data_bytes,
                       stdout=subprocess.PIPE, stderr=subprocess.PIPE, env=env, timeout=timeout)
    return p

def check_fixtures(candidate='submission/main.py', fixtures='examples/checks.json'):
    fx = json.load(open(fixtures))
    ok = 0
    for i, f in enumerate(fx):
        data = f.get('raw')
        if data is None: data = json.dumps(f['request'], separators=(',', ':'))
        p = run(candidate, data.encode('utf-8'))
        if p.returncode != 0:
            print(f'FAIL fixture {i}: rc={p.returncode} stderr={p.stderr.decode()[:400]}'); return 1
        try:
            result = strict_load(p.stdout)
        except Exception as e:
            print(f'FAIL fixture {i}: bad json {e}: {p.stdout[:200]}'); return 1
        if not same(result, f['response']):
            print(f'FAIL fixture {i}: mismatch\n got: {p.stdout.decode()[:1500]}\n exp: {json.dumps(f["response"])[:1500]}'); return 1
        ok += 1
    print(f'PASS {ok} fixtures')
    return 0

if __name__ == '__main__':
    sys.exit(check_fixtures(*sys.argv[1:]))
