//! Transactional certificate layer for weighted cache-group reconfigurations.
//!
//! The ledger keeps the committed configuration and certifies proposals built
//! from ordered field assignments.  Committed state is never destroyed by a
//! rejected proposal: every speculative mutation is recorded in a journal of
//! inverse operations which is replayed backwards on rejection.  All validity
//! decisions (node capacity, group homogeneity, weighted work budgets and pin
//! protection) are computed exactly on the final proposal.

use crate::solver::SolverProblem;
use std::collections::HashMap;

/// One service task bound to a template and a cache group.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

/// Domain of every template, derived from the topology scope of the session.
///
/// `code`/`args` are the encoded topology descriptor produced by the transport
/// layer; endpoint pairs come from the routing templates themselves.
pub fn template_domains(code: usize, args: &[usize], problem: &SolverProblem) -> Vec<i64> {
    let mut out = Vec::with_capacity(problem.demands.len());
    for demand in &problem.demands {
        let src = demand.src as i64;
        let dst = demand.dst as i64;
        let value = match code {
            // clos: args = [k, pod-scope, intra]
            0 => if args[1] != 0 { src / (args[0] as i64 / 2) } else { src },
            // leaf-spine
            1 => src,
            // torus2d / torus3d: args = [n, row/line scope]
            2 | 3 => if args[1] != 0 { src / args[0] as i64 } else { src },
            // dragonfly: args = [g, a, h, 0=router 1=group 2=target]
            4 => match args[3] {
                1 => src / args[1] as i64,
                2 => src * args[0] as i64 + dst / args[1] as i64,
                _ => src,
            },
            // dragonfly-plus: args = [g, l, s, h, dense, group-scope]
            5 => {
                let span = (args[1] + args[2]) as i64;
                let leaves = args[1] as i64;
                if args[5] != 0 { src / span } else { (src / span) * leaves + src % span }
            }
            _ => src,
        };
        out.push(value);
    }
    out
}

/// Journal entry: enough information to mirror one committed mutation.
#[derive(Clone, Copy, Debug)]
enum Undo {
    Move(usize, usize),
    Bind(usize, usize),
    Weight(usize, u64),
    Class(usize, u64),
    Pin(usize, bool),
    Quota(usize, u64),
    Budget(usize, u64),
    Cap(usize, u64),
}

/// Start-of-transaction snapshot of a touched service task.
struct TaskSnap {
    id: usize,
    group: usize,
    template: usize,
    weight: u64,
    class: u64,
    pinned: bool,
}

/// Start-of-transaction snapshot of a group touched by a quota assignment.
struct GroupSnap {
    id: usize,
    quota: u64,
    pins: i64,
}

pub struct Ledger {
    num_nodes: usize,
    words: usize,
    /// Cache-bearing footprint of every routing template, as a bit set.
    template_fp: Vec<u64>,
    /// Cache domain of every routing template.
    dom: Vec<i64>,

    task: Vec<Task>,
    quota: Vec<u64>,

    self.total_weight += delta;
    self.task[id].weight = weight;
    self.update_work(group);
}

fn set_class_raw(&mut self, id: usize, class: u64) {
    if self.task[id].class == class {
        return;
    }
    let group = self.task[id].group;
    let key = (self.dom[self.task[id].template], self.task[id].class as i64);
    self.drop_key(group, key);
    self.task[id].class = class;
    let key = (self.dom[self.task[id].template], class as i64);
    self.bump_key(group, key);
}

fn set_pin_raw(&mut self, id: usize, pinned: bool) {
    if self.task[id].pinned == pinned {
        return;
    }
    let group = self.task[id].group;
    self.task[id].pinned = pinned;
    if pinned {
        self.pins += 1;
        self.pin_in_group[group] += 1;
    } else {
        self.pins -= 1;
        self.pin_in_group[group] -= 1;
    }
}

fn set_cap_raw(&mut self, node: usize, capacity: u64) {
    let value = capacity as i64;
    if self.caps[node] == value {
        return;
    }
    self.caps[node] = value;
    self.recheck_over(node);
}

fn set_budget_raw(&mut self, group: usize, budget: u64) {
    if self.budget[group] == budget {
        return;
    }
    self.budget[group] = budget;
    self.update_work(group);
}

fn set_quota_raw(&mut self, group: usize, quota: u64) {
    if self.quota[group] == quota {
        return;
    }
    let delta = quota as i64 - self.quota[group] as i64;
    let gbase = group * self.words;
    for word_index in 0..self.words {
        let mut word = self.union_fp[gbase + word_index];
        while word != 0 {
            let bit = word.trailing_zeros() as usize;
            word &= word - 1;
            let node = word_index * 64 + bit;
            self.usage[node] += delta;
            self.recheck_over(node);
        }
    }
    self.slots += delta * self.fp_size[group];
    self.quota[group] = quota;
    self.update_work(group);
}

fn move_raw(&mut self, id: usize, group: usize) {
    if self.task[id].group == group {
        return;
    }
    let old = self.task[id].group;
    self.detach(id, old);
    self.task[id].group = group;
    self.attach(id, group);
}

fn bind_raw(&mut self, id: usize, template: usize) {
    if self.task[id].template == template {
        return;
    }
    let group = self.task[id].group;
    self.detach(id, group);
    self.task[id].template = template;
    self.attach(id, group);
}

// ------------------------------------------------------- journal layer

fn apply(&mut self, edit: Edit) {
    match edit {
        Edit::Move(id, group) => {
            if self.task[id].group != group {
                self.journal.push(Undo::Move(id, self.task[id].group));
                self.move_raw(id, group);
            }
        }
        Edit::Bind(id, template) => {
            if self.task[id].template != template {
                self.journal.push(Undo::Bind(id, self.task[id].template));
                self.bind_raw(id, template);
            }
        }
        Edit::Weight(id, weight) => {
            if self.task[id].weight != weight {
                self.journal.push(Undo::Weight(id, self.task[id].weight));
                self.set_weight_raw(id, weight);
            }
        }
        Edit::Class(id, class) => {
            if self.task[id].class != class {
                self.journal.push(Undo::Class(id, self.task[id].class));
                self.set_class_raw(id, class);
            }
        }
        Edit::Pin(id, pinned) => {
            if self.task[id].pinned != pinned {
                self.journal.push(Undo::Pin(id, self.task[id].pinned));
                self.set_pin_raw(id, pinned);
            }
        }
        Edit::Quota(group, quota) => {
            if self.quota[group] != quota {
                self.journal.push(Undo::Quota(group, self.quota[group]));
                self.set_quota_raw(group, quota);
            }
        }
        Edit::Budget(group, budget) => {
            if self.budget[group] != budget {
                self.journal.push(Undo::Budget(group, self.budget[group]));
                self.set_budget_raw(group, budget);
            }
        }
        Edit::Cap(node, capacity) => {
            if self.caps[node] != capacity as i64 {
                self.journal.push(Undo::Cap(node, self.caps[node] as u64));
                self.set_cap_raw(node, capacity);
            }
        }
    }
}

fn rollback(&mut self) {
    while let Some(entry) = self.journal.pop() {
        match entry {
            Undo::Move(id, group) => self.move_raw(id, group),
            Undo::Bind(id, template) => self.bind_raw(id, template),
            Undo::Weight(id, weight) => self.set_weight_raw(id, weight),
            Undo::Class(id, class) => self.set_class_raw(id, class),
            Undo::Pin(id, pinned) => self.set_pin_raw(id, pinned),
            Undo::Quota(group, quota) => self.set_quota_raw(group, quota),
            Undo::Budget(group, budget) => self.set_budget_raw(group, budget),
            Undo::Cap(node, capacity) => self.set_cap_raw(node, capacity),
        }
    }
}

