    pub fn new(
        problem: &SolverProblem,
        domains: Vec<i64>,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let num_nodes = problem.num_nodes;
        if capacities.len() != num_nodes {
            return Err("capacity count".into());
        }
        if quotas.len() != budgets.len() {
            return Err("group table".into());
        }
        if domains.len() != problem.demands.len() {
            return Err("domain table".into());
        }
        for &cap in &capacities {
            if cap > i64::MAX as u64 {
                return Err("capacity range".into());
            }
        }
        let words = num_nodes.div_ceil(64);
        let templates = problem.demands.len();
        let mut template_fp = vec![0u64; templates * words];
        for (id, demand) in problem.demands.iter().enumerate() {
            for &node in &demand.footprint {
                if node >= num_nodes {
                    return Err("footprint node".into());
                }
                template_fp[id * words + node / 64] |= 1u64 << (node % 64);
            }
        }
        let groups = quotas.len();
        let task_count = tasks.len();
        for task in &tasks {
            if task.group >= groups {
                return Err("task group".into());
            }
            if task.template >= templates {
                return Err("task template".into());
            }
        }

        let mut ledger = Ledger {
            num_nodes,
            words,
            template_fp,
            dom: domains,
            task: tasks,
            quota: quotas,
            budget: budgets,
            cnt: vec![0u32; groups * num_nodes],
            union_fp: vec![0u64; groups * words],
            fp_size: vec![0i64; groups],
            members: vec![0i64; groups],
            load: vec![0i64; groups],
            keys: (0..groups).map(|_| HashMap::new()).collect(),
            g_dom: vec![-1i64; groups],
            g_cls: vec![-1i64; groups],
            usage: vec![0i64; num_nodes],
            caps: capacities.iter().map(|&x| x as i64).collect(),
            over_flag: vec![false; num_nodes],
            work_flag: vec![false; groups],
            overcap: 0,
            mixed: 0,
            workbad: 0,
            active: 0,
            slots: 0,
            total_weight: 0,
            pins: 0,
            pin_in_group: vec![0i64; groups],
            revision: 0,
            journal: Vec::new(),
            snaps: Vec::new(),
            group_snaps: Vec::new(),
            task_stamp: vec![0u32; task_count],
            task_slot: vec![0u32; task_count],
            group_stamp: vec![0u32; groups],
            group_slot: vec![0u32; groups],
            txn: 0,
        };
        for id in 0..ledger.task.len() {
            let group = ledger.task[id].group;
            ledger.attach(id, group);
        }
        if ledger.overcap != 0 || ledger.mixed != 0 || ledger.workbad != 0 {
            return Err("illegal initial configuration".into());
        }
        Ok(ledger)
    }

